// Phase 3 Day 1-2: Test Generator
// 의도별 자동 테스트 생성 (Positive + EdgeCase + Negative + Performance)

use crate::phase2::intent_parser::*;
use crate::phase2::code_generator::*;

enum TestType {
    Positive,      // 정상 케이스
    EdgeCase,      // 경계값
    Negative,      // 에러 케이스
    Performance    // 성능 테스트
}

struct TestCase {
    test_type: TestType,
    intent: Intent,
    input_data: Vec<String>,
    expected_output: String,
    description: String
}

struct TestGenerator {
    intent_type: IntentType,
    generated_tests: Vec<TestCase>,
    total_count: i32
}

// ===== Test Template Functions =====

fn generate_compute_tests() -> Vec<TestCase> {
    let mut tests = vec![];

    // Positive: Add
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::Compute,
            raw_input: "5 + 3".to_string(),
            params: vec!["5".to_string(), "3".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["더하기".to_string()]
        },
        input_data: vec!["5".to_string(), "3".to_string()],
        expected_output: "8".to_string(),
        description: "Basic addition: 5 + 3 = 8".to_string()
    });

    // Positive: Multiply
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::Compute,
            raw_input: "4 * 2".to_string(),
            params: vec!["4".to_string(), "2".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["곱하기".to_string()]
        },
        input_data: vec!["4".to_string(), "2".to_string()],
        expected_output: "8".to_string(),
        description: "Basic multiplication: 4 * 2 = 8".to_string()
    });

    // EdgeCase: Zero operand
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Compute,
            raw_input: "0 + 0".to_string(),
            params: vec!["0".to_string(), "0".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["영".to_string()]
        },
        input_data: vec!["0".to_string(), "0".to_string()],
        expected_output: "0".to_string(),
        description: "Edge case: 0 + 0 = 0".to_string()
    });

    // EdgeCase: Negative numbers
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Compute,
            raw_input: "-5 + 5".to_string(),
            params: vec!["-5".to_string(), "5".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["음수".to_string()]
        },
        input_data: vec!["-5".to_string(), "5".to_string()],
        expected_output: "0".to_string(),
        description: "Edge case: -5 + 5 = 0 (opposite negation)".to_string()
    });

    // Negative: Division by zero
    tests.push(TestCase {
        test_type: TestType::Negative,
        intent: Intent {
            intent_type: IntentType::Compute,
            raw_input: "10 / 0".to_string(),
            params: vec!["10".to_string(), "0".to_string()],
            confidence: 0.85,
            matched_keywords: vec!["나누기".to_string()]
        },
        input_data: vec!["10".to_string(), "0".to_string()],
        expected_output: "error".to_string(),
        description: "Negative: Division by zero should fail".to_string()
    });

    // Performance: Large numbers
    tests.push(TestCase {
        test_type: TestType::Performance,
        intent: Intent {
            intent_type: IntentType::Compute,
            raw_input: "1000000 + 1000000".to_string(),
            params: vec!["1000000".to_string(), "1000000".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["큰숫자".to_string()]
        },
        input_data: vec!["1000000".to_string(), "1000000".to_string()],
        expected_output: "2000000".to_string(),
        description: "Performance: Large number addition < 100ms".to_string()
    });

    tests
}

fn generate_transform_tests() -> Vec<TestCase> {
    let mut tests = vec![];

    // Positive: Uppercase
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::Transform,
            raw_input: "hello를 대문자로".to_string(),
            params: vec!["hello".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["대문자".to_string()]
        },
        input_data: vec!["hello".to_string()],
        expected_output: "HELLO".to_string(),
        description: "Basic uppercase transform".to_string()
    });

    // EdgeCase: Empty string
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Transform,
            raw_input: "빈문자열 대문자".to_string(),
            params: vec!["".to_string()],
            confidence: 0.85,
            matched_keywords: vec!["빈".to_string()]
        },
        input_data: vec!["".to_string()],
        expected_output: "".to_string(),
        description: "Edge case: Empty string remains empty".to_string()
    });

    // EdgeCase: Numbers and symbols
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Transform,
            raw_input: "123!@# 대문자".to_string(),
            params: vec!["123!@#".to_string()],
            confidence: 0.8,
            matched_keywords: vec!["기호".to_string()]
        },
        input_data: vec!["123!@#".to_string()],
        expected_output: "123!@#".to_string(),
        description: "Edge case: Numbers and symbols unchanged".to_string()
    });

    // Negative: Null input
    tests.push(TestCase {
        test_type: TestType::Negative,
        intent: Intent {
            intent_type: IntentType::Transform,
            raw_input: "null입력".to_string(),
            params: vec![],
            confidence: 0.7,
            matched_keywords: vec!["null".to_string()]
        },
        input_data: vec![],
        expected_output: "error".to_string(),
        description: "Negative: Null input should error".to_string()
    });

    // Performance: Long string
    tests.push(TestCase {
        test_type: TestType::Performance,
        intent: Intent {
            intent_type: IntentType::Transform,
            raw_input: "긴문자열 변환".to_string(),
            params: vec!["abcdefghijklmnopqrstuvwxyz".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["긴".to_string()]
        },
        input_data: vec!["abcdefghijklmnopqrstuvwxyz".to_string()],
        expected_output: "ABCDEFGHIJKLMNOPQRSTUVWXYZ".to_string(),
        description: "Performance: Long string transform < 50ms".to_string()
    });

    tests
}

fn generate_filter_tests() -> Vec<TestCase> {
    let mut tests = vec![];

    // Positive: Filter even numbers
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::Filter,
            raw_input: "짝수만 필터".to_string(),
            params: vec!["1,2,3,4,5,6".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["짝수".to_string()]
        },
        input_data: vec!["1,2,3,4,5,6".to_string()],
        expected_output: "2,4,6".to_string(),
        description: "Filter even numbers from array".to_string()
    });

    // EdgeCase: All elements match
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Filter,
            raw_input: "2,4,6을 짝수 필터".to_string(),
            params: vec!["2,4,6".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["모두".to_string()]
        },
        input_data: vec!["2,4,6".to_string()],
        expected_output: "2,4,6".to_string(),
        description: "Edge case: All elements pass filter".to_string()
    });

    // EdgeCase: No elements match
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Filter,
            raw_input: "1,3,5를 짝수 필터".to_string(),
            params: vec!["1,3,5".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["없음".to_string()]
        },
        input_data: vec!["1,3,5".to_string()],
        expected_output: "".to_string(),
        description: "Edge case: No elements pass filter".to_string()
    });

    // Negative: Empty array
    tests.push(TestCase {
        test_type: TestType::Negative,
        intent: Intent {
            intent_type: IntentType::Filter,
            raw_input: "빈배열 필터".to_string(),
            params: vec![],
            confidence: 0.7,
            matched_keywords: vec!["빈".to_string()]
        },
        input_data: vec![],
        expected_output: "error".to_string(),
        description: "Negative: Empty array should error".to_string()
    });

    // Performance: Large array
    tests.push(TestCase {
        test_type: TestType::Performance,
        intent: Intent {
            intent_type: IntentType::Filter,
            raw_input: "큰배열 짝수필터".to_string(),
            params: vec!["10000개".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["큰".to_string()]
        },
        input_data: vec!["10000".to_string()],
        expected_output: "5000".to_string(),
        description: "Performance: Filter 10k elements < 200ms".to_string()
    });

    tests
}

fn generate_aggregate_tests() -> Vec<TestCase> {
    let mut tests = vec![];

    // Positive: Average
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::Aggregate,
            raw_input: "평균 계산".to_string(),
            params: vec!["10,20,30".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["평균".to_string()]
        },
        input_data: vec!["10,20,30".to_string()],
        expected_output: "20".to_string(),
        description: "Calculate average: (10+20+30)/3 = 20".to_string()
    });

    // EdgeCase: Single element
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Aggregate,
            raw_input: "한개만 평균".to_string(),
            params: vec!["42".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["한개".to_string()]
        },
        input_data: vec!["42".to_string()],
        expected_output: "42".to_string(),
        description: "Edge case: Average of single element = itself".to_string()
    });

    // EdgeCase: Negative average
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Aggregate,
            raw_input: "-10,-20,-30 평균".to_string(),
            params: vec!["-10,-20,-30".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["음수".to_string()]
        },
        input_data: vec!["-10,-20,-30".to_string()],
        expected_output: "-20".to_string(),
        description: "Edge case: Average of negative numbers".to_string()
    });

    // Negative: Empty set
    tests.push(TestCase {
        test_type: TestType::Negative,
        intent: Intent {
            intent_type: IntentType::Aggregate,
            raw_input: "빈집합 평균".to_string(),
            params: vec![],
            confidence: 0.7,
            matched_keywords: vec!["빈".to_string()]
        },
        input_data: vec![],
        expected_output: "error".to_string(),
        description: "Negative: Average of empty set should error".to_string()
    });

    // Performance: Large aggregate
    tests.push(TestCase {
        test_type: TestType::Performance,
        intent: Intent {
            intent_type: IntentType::Aggregate,
            raw_input: "10000개 평균".to_string(),
            params: vec!["10000".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["큰".to_string()]
        },
        input_data: vec!["10000".to_string()],
        expected_output: "5000".to_string(),
        description: "Performance: Aggregate 10k elements < 100ms".to_string()
    });

    tests
}

fn generate_control_tests() -> Vec<TestCase> {
    let mut tests = vec![];

    // Positive: Loop 1 to 10
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::Control,
            raw_input: "1부터 10까지 반복".to_string(),
            params: vec!["10".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["반복".to_string()]
        },
        input_data: vec!["10".to_string()],
        expected_output: "10".to_string(),
        description: "Loop 1 to 10: execute 10 times".to_string()
    });

    // EdgeCase: Zero iterations
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Control,
            raw_input: "0번 반복".to_string(),
            params: vec!["0".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["없음".to_string()]
        },
        input_data: vec!["0".to_string()],
        expected_output: "0".to_string(),
        description: "Edge case: 0 iterations = skip loop".to_string()
    });

    // EdgeCase: Large iteration count
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Control,
            raw_input: "1000번 반복".to_string(),
            params: vec!["1000".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["많이".to_string()]
        },
        input_data: vec!["1000".to_string()],
        expected_output: "1000".to_string(),
        description: "Edge case: Large loop count".to_string()
    });

    // Negative: Negative iterations
    tests.push(TestCase {
        test_type: TestType::Negative,
        intent: Intent {
            intent_type: IntentType::Control,
            raw_input: "-5번 반복".to_string(),
            params: vec!["-5".to_string()],
            confidence: 0.7,
            matched_keywords: vec!["음수".to_string()]
        },
        input_data: vec!["-5".to_string()],
        expected_output: "error".to_string(),
        description: "Negative: Negative iterations should error".to_string()
    });

    // Performance: Nested loops
    tests.push(TestCase {
        test_type: TestType::Performance,
        intent: Intent {
            intent_type: IntentType::Control,
            raw_input: "중첩루프".to_string(),
            params: vec!["100".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["중첩".to_string()]
        },
        input_data: vec!["100".to_string()],
        expected_output: "10000".to_string(),
        description: "Performance: Nested loop 100x100 < 500ms".to_string()
    });

    tests
}

fn generate_validate_tests() -> Vec<TestCase> {
    let mut tests = vec![];

    // Positive: Valid input
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::Validate,
            raw_input: "이메일 검증".to_string(),
            params: vec!["test@example.com".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["이메일".to_string()]
        },
        input_data: vec!["test@example.com".to_string()],
        expected_output: "true".to_string(),
        description: "Valid email format".to_string()
    });

    // EdgeCase: Minimal email
    tests.push(TestCase {
        test_type: TestType::EdgeCase,
        intent: Intent {
            intent_type: IntentType::Validate,
            raw_input: "최소이메일".to_string(),
            params: vec!["a@b".to_string()],
            confidence: 0.8,
            matched_keywords: vec!["최소".to_string()]
        },
        input_data: vec!["a@b".to_string()],
        expected_output: "true".to_string(),
        description: "Edge case: Minimal valid email".to_string()
    });

    // Negative: Invalid format
    tests.push(TestCase {
        test_type: TestType::Negative,
        intent: Intent {
            intent_type: IntentType::Validate,
            raw_input: "잘못된이메일".to_string(),
            params: vec!["notanemail".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["잘못".to_string()]
        },
        input_data: vec!["notanemail".to_string()],
        expected_output: "false".to_string(),
        description: "Invalid email: no @domain".to_string()
    });

    // Performance: Batch validation
    tests.push(TestCase {
        test_type: TestType::Performance,
        intent: Intent {
            intent_type: IntentType::Validate,
            raw_input: "배치검증".to_string(),
            params: vec!["1000".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["많이".to_string()]
        },
        input_data: vec!["1000".to_string()],
        expected_output: "1000".to_string(),
        description: "Performance: Validate 1000 items < 300ms".to_string()
    });

    tests
}

fn generate_io_tests() -> Vec<TestCase> {
    let mut tests = vec![];

    // Positive: Parse JSON
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::IO,
            raw_input: "JSON 파싱".to_string(),
            params: vec!["{\"key\": \"value\"}".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["JSON".to_string()]
        },
        input_data: vec!["{\"key\": \"value\"}".to_string()],
        expected_output: "parsed".to_string(),
        description: "Parse valid JSON".to_string()
    });

    // Negative: Invalid JSON
    tests.push(TestCase {
        test_type: TestType::Negative,
        intent: Intent {
            intent_type: IntentType::IO,
            raw_input: "잘못된JSON".to_string(),
            params: vec!["{bad json}".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["잘못".to_string()]
        },
        input_data: vec!["{bad json}".to_string()],
        expected_output: "error".to_string(),
        description: "Invalid JSON should error".to_string()
    });

    // Performance: Large JSON
    tests.push(TestCase {
        test_type: TestType::Performance,
        intent: Intent {
            intent_type: IntentType::IO,
            raw_input: "큰JSON".to_string(),
            params: vec!["1MB".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["큰".to_string()]
        },
        input_data: vec!["1000000".to_string()],
        expected_output: "parsed".to_string(),
        description: "Performance: Parse 1MB JSON < 1000ms".to_string()
    });

    tests
}

fn generate_format_tests() -> Vec<TestCase> {
    let mut tests = vec![];

    // Positive: Number formatting
    tests.push(TestCase {
        test_type: TestType::Positive,
        intent: Intent {
            intent_type: IntentType::Format,
            raw_input: "숫자 포맷".to_string(),
            params: vec!["1000".to_string()],
            confidence: 0.95,
            matched_keywords: vec!["포맷".to_string()]
        },
        input_data: vec!["1000".to_string()],
        expected_output: "1,000".to_string(),
        description: "Format number with commas: 1000 -> 1,000".to_string()
    });

    // Performance: Batch formatting
    tests.push(TestCase {
        test_type: TestType::Performance,
        intent: Intent {
            intent_type: IntentType::Format,
            raw_input: "배치포맷".to_string(),
            params: vec!["10000".to_string()],
            confidence: 0.9,
            matched_keywords: vec!["많이".to_string()]
        },
        input_data: vec!["10000".to_string()],
        expected_output: "formatted".to_string(),
        description: "Performance: Format 10k numbers < 200ms".to_string()
    });

    tests
}

impl TestGenerator {
    fn new(intent_type: IntentType) -> TestGenerator {
        TestGenerator {
            intent_type,
            generated_tests: vec![],
            total_count: 0
        }
    }

    fn generate_tests(mut self) -> TestGenerator {
        self.generated_tests = match self.intent_type {
            IntentType::Compute => generate_compute_tests(),
            IntentType::Transform => generate_transform_tests(),
            IntentType::Filter => generate_filter_tests(),
            IntentType::Aggregate => generate_aggregate_tests(),
            IntentType::Control => generate_control_tests(),
            IntentType::Validate => generate_validate_tests(),
            IntentType::IO => generate_io_tests(),
            IntentType::Format => generate_format_tests(),
            IntentType::Unknown => vec![]
        };

        self.total_count = self.generated_tests.len() as i32;
        self
    }

    fn get_tests_by_type(self, test_type: TestType) -> Vec<TestCase> {
        let mut filtered = vec![];
        for test in self.generated_tests {
            match (test.test_type, test_type) {
                (TestType::Positive, TestType::Positive) => filtered.push(test),
                (TestType::EdgeCase, TestType::EdgeCase) => filtered.push(test),
                (TestType::Negative, TestType::Negative) => filtered.push(test),
                (TestType::Performance, TestType::Performance) => filtered.push(test),
                _ => {}
            }
        }
        filtered
    }

    fn get_positive_tests(self) -> Vec<TestCase> {
        self.get_tests_by_type(TestType::Positive)
    }

    fn get_edge_case_tests(self) -> Vec<TestCase> {
        self.get_tests_by_type(TestType::EdgeCase)
    }

    fn get_negative_tests(self) -> Vec<TestCase> {
        self.get_tests_by_type(TestType::Negative)
    }

    fn get_performance_tests(self) -> Vec<TestCase> {
        self.get_tests_by_type(TestType::Performance)
    }
}

fn create_test_generator(intent_type: IntentType) -> TestGenerator {
    TestGenerator::new(intent_type).generate_tests()
}

fn count_tests_for_intent(intent_type: IntentType) -> i32 {
    create_test_generator(intent_type).total_count
}

fn generate_all_tests() -> Vec<TestCase> {
    let mut all_tests = vec![];

    let intent_types = vec![
        IntentType::Compute,
        IntentType::Transform,
        IntentType::Filter,
        IntentType::Aggregate,
        IntentType::Control,
        IntentType::Validate,
        IntentType::IO,
        IntentType::Format
    ];

    for intent_type in intent_types {
        let gen = create_test_generator(intent_type);
        for test in gen.generated_tests {
            all_tests.push(test);
        }
    }

    all_tests
}

fn count_total_tests() -> i32 {
    generate_all_tests().len() as i32
}

