impl TestGenerator {
    fn new(intent_type: IntentType) -> TestGenerator {
        TestGenerator {
            intent_type,
            generated_tests: vec![],
            total_count: 0
        }
    }

    fn generate_tests(mut self) -> TestGenerator {
        self.generated_tests = match self.intent_type {
            IntentType::Compute => generate_compute_tests(),
            IntentType::Transform => generate_transform_tests(),
            IntentType::Filter => generate_filter_tests(),
            IntentType::Aggregate => generate_aggregate_tests(),
            IntentType::Control => generate_control_tests(),
            IntentType::Validate => generate_validate_tests(),
            IntentType::IO => generate_io_tests(),
            IntentType::Format => generate_format_tests(),
            IntentType::Unknown => vec![]
        };

        self.total_count = self.generated_tests.len() as i32;
        self
    }

    fn get_tests_by_type(self, test_type: TestType) -> Vec<TestCase> {
        let mut filtered = vec![];
        for test in self.generated_tests {
            match (test.test_type, test_type) {
                (TestType::Positive, TestType::Positive) => filtered.push(test),
                (TestType::EdgeCase, TestType::EdgeCase) => filtered.push(test),
                (TestType::Negative, TestType::Negative) => filtered.push(test),
                (TestType::Performance, TestType::Performance) => filtered.push(test),
                _ => {}
            }
        }
        filtered
    }

    fn get_positive_tests(self) -> Vec<TestCase> {
        self.get_tests_by_type(TestType::Positive)
    }

    fn get_edge_case_tests(self) -> Vec<TestCase> {
        self.get_tests_by_type(TestType::EdgeCase)
    }

    fn get_negative_tests(self) -> Vec<TestCase> {
        self.get_tests_by_type(TestType::Negative)
    }

    fn get_performance_tests(self) -> Vec<TestCase> {
        self.get_tests_by_type(TestType::Performance)
    }
}

fn create_test_generator(intent_type: IntentType) -> TestGenerator {
    TestGenerator::new(intent_type).generate_tests()
}

fn count_tests_for_intent(intent_type: IntentType) -> i32 {
    create_test_generator(intent_type).total_count
}

fn generate_all_tests() -> Vec<TestCase> {
    let mut all_tests = vec![];

    let intent_types = vec![
        IntentType::Compute,
        IntentType::Transform,
        IntentType::Filter,
        IntentType::Aggregate,
        IntentType::Control,
        IntentType::Validate,
        IntentType::IO,
        IntentType::Format
    ];

    for intent_type in intent_types {
        let gen = create_test_generator(intent_type);
        for test in gen.generated_tests {
            all_tests.push(test);
        }
    }

    all_tests
}

fn count_total_tests() -> i32 {
    generate_all_tests().len() as i32
}

