// Phase 3 Day 3-4: Error Analyzer
// 테스트 실패 분석 및 에러 분류

use crate::phase3::test_generator::*;

enum ErrorType {
    CompilationError,
    RuntimeError,
    LogicError,
    PerformanceIssue,
    MemoryLeak,
    TypeMismatch,
    BoundsError,
    NullPointer,
    Timeout,
    Unknown
}

struct ErrorAnalysis {
    error_type: ErrorType,
    location: String,
    message: String,
    severity: i32,      // 1-10
    frequency: i32,     // 몇 번 발생
    affected_tests: Vec<String>
}

struct TestResult {
    test_case: TestCase,
    passed: bool,
    error_message: String,
    execution_time_ms: i32
}

struct ErrorAnalyzer {
    test_results: Vec<TestResult>,
    errors: Vec<ErrorAnalysis>,
    error_patterns: Vec<String>
}

// ===== Error Classification Logic =====

fn classify_error(error_message: String) -> ErrorType {
    if contains(error_message.clone(), "cannot borrow") {
        ErrorType::RuntimeError
    } else if contains(error_message.clone(), "type mismatch") {
        ErrorType::TypeMismatch
    } else if contains(error_message.clone(), "index out of bounds") {
        ErrorType::BoundsError
    } else if contains(error_message.clone(), "execution took") {
        ErrorType::PerformanceIssue
    } else if contains(error_message.clone(), "memory usage") {
        ErrorType::MemoryLeak
    } else if contains(error_message.clone(), "null pointer") {
        ErrorType::NullPointer
    } else if contains(error_message.clone(), "timeout") {
        ErrorType::Timeout
    } else if contains(error_message.clone(), "undefined") {
        ErrorType::RuntimeError
    } else if contains(error_message.clone(), "division by zero") {
        ErrorType::RuntimeError
    } else if contains(error_message.clone(), "compilation failed") {
        ErrorType::CompilationError
    } else {
        ErrorType::Unknown
    }
}

fn contains(text: String, pattern: String) -> bool {
    // Simple substring check
    let text_lower = text.to_lowercase();
    let pattern_lower = pattern.to_lowercase();

    // Very basic contains check
    for i in 0..(text_lower.len()) {
        let mut matches = true;
        for j in 0..pattern_lower.len() {
            if i + j >= text_lower.len() {
                matches = false;
                break;
            }
        }
        if matches {
            return true;
        }
    }
    false
}

fn calculate_severity(error_type: ErrorType) -> i32 {
    match error_type {
        ErrorType::CompilationError => 8,
        ErrorType::RuntimeError => 8,
        ErrorType::NullPointer => 9,
        ErrorType::BoundsError => 8,
        ErrorType::Timeout => 7,
        ErrorType::MemoryLeak => 8,
        ErrorType::TypeMismatch => 7,
        ErrorType::PerformanceIssue => 5,
        ErrorType::LogicError => 6,
        ErrorType::Unknown => 4
    }
}

fn categorize_pattern(message: String) -> String {
    if contains(message.clone(), "type") {
        "TypeSystem".to_string()
    } else if contains(message.clone(), "memory") {
        "MemoryManagement".to_string()
    } else if contains(message.clone(), "bounds") {
        "ArrayAccess".to_string()
    } else if contains(message.clone(), "null") {
        "NullCheck".to_string()
    } else if contains(message.clone(), "timeout") {
        "Performance".to_string()
    } else if contains(message.clone(), "borrow") {
        "Ownership".to_string()
    } else {
        "Other".to_string()
    }
}

impl ErrorAnalyzer {
    fn new() -> ErrorAnalyzer {
        ErrorAnalyzer {
            test_results: vec![],
            errors: vec![],
            error_patterns: vec![]
        }
    }

    fn add_test_result(mut self, result: TestResult) -> ErrorAnalyzer {
        self.test_results.push(result);
        self
    }

    fn analyze(mut self) -> ErrorAnalyzer {
        let mut error_map = vec![];
        let mut patterns = vec![];

        for result in &self.test_results {
            if !result.passed && result.error_message.len() > 0 {
                let error_type = classify_error(result.error_message.clone());
                let pattern = categorize_pattern(result.error_message.clone());

                // Track pattern
                let mut found = false;
                for p in &patterns {
                    if p == &pattern {
                        found = true;
                        break;
                    }
                }
                if !found {
                    patterns.push(pattern);
                }

                // Track error
                let mut found_error = false;
                for err in &mut error_map {
                    match err {
                        (et, loc, msg, freq) => {
                            // Simple check for same error
                            if msg == &result.error_message {
                                *freq = *freq + 1;
                                found_error = true;
                                break;
                            }
                        }
                    }
                }

                if !found_error {
                    error_map.push((
                        error_type,
                        result.test_case.description.clone(),
                        result.error_message.clone(),
                        1
                    ));
                }
            }
        }

        // Build error analysis list
        for (error_type, location, message, frequency) in error_map {
            let severity = calculate_severity(error_type);

            let mut affected = vec![];
            for result in &self.test_results {
                if !result.passed && result.error_message == message {
                    affected.push(result.test_case.description.clone());
                }
            }

            self.errors.push(ErrorAnalysis {
                error_type,
                location,
                message,
                severity,
                frequency,
                affected_tests: affected
            });
        }

        self.error_patterns = patterns;
        self
    }

    fn get_critical_errors(self) -> Vec<ErrorAnalysis> {
        let mut critical = vec![];
        for error in self.errors {
            if error.severity >= 7 {
                critical.push(error);
            }
        }
        critical
    }

    fn get_error_summary(self) -> (i32, i32, i32) {
        let total = self.test_results.len() as i32;
        let mut failed = 0;
        let mut critical = 0;

        for result in &self.test_results {
            if !result.passed {
                failed = failed + 1;
            }
        }

        for error in &self.errors {
            if error.severity >= 8 {
                critical = critical + 1;
            }
        }

        (total, failed, critical)
    }

    fn error_count_by_type(self) -> Vec<(String, i32)> {
        let mut counts = vec![];

        for error in self.errors {
            let error_name = match error.error_type {
                ErrorType::CompilationError => "CompilationError".to_string(),
                ErrorType::RuntimeError => "RuntimeError".to_string(),
                ErrorType::LogicError => "LogicError".to_string(),
                ErrorType::PerformanceIssue => "PerformanceIssue".to_string(),
                ErrorType::MemoryLeak => "MemoryLeak".to_string(),
                ErrorType::TypeMismatch => "TypeMismatch".to_string(),
                ErrorType::BoundsError => "BoundsError".to_string(),
                ErrorType::NullPointer => "NullPointer".to_string(),
                ErrorType::Timeout => "Timeout".to_string(),
                ErrorType::Unknown => "Unknown".to_string()
            };

            let mut found = false;
            for (name, count) in &mut counts {
                if name == &error_name {
                    *count = *count + 1;
                    found = true;
                    break;
                }
            }

            if !found {
                counts.push((error_name, 1));
            }
        }

        counts
    }

    fn get_top_patterns(self, limit: i32) -> Vec<String> {
        let mut result = vec![];
        let mut i = 0;
        for pattern in self.error_patterns {
            if i >= limit {
                break;
            }
            result.push(pattern);
            i = i + 1;
        }
        result
    }
}

// ===== Analyzer Helper Functions =====

fn create_error_analyzer() -> ErrorAnalyzer {
    ErrorAnalyzer::new()
}

fn analyze_test_failures(results: Vec<TestResult>) -> ErrorAnalyzer {
    let mut analyzer = ErrorAnalyzer::new();

    for result in results {
        analyzer = analyzer.add_test_result(result);
    }

    analyzer.analyze()
}

fn get_failure_rate(analyzer: ErrorAnalyzer) -> f32 {
    let (total, failed, _) = analyzer.get_error_summary();

    if total == 0 {
        0.0
    } else {
        (failed as f32 / total as f32) * 100.0
    }
}

fn get_critical_error_count(analyzer: ErrorAnalyzer) -> i32 {
    analyzer.get_critical_errors().len() as i32
}

fn recommend_fix_priority(analyzer: ErrorAnalyzer) -> Vec<String> {
    let mut recommendations = vec![];
    let errors = analyzer.errors;

    // Sort by severity (simple bubble sort)
    let mut sorted_errors = errors.clone();
    let mut i = 0;
    while i < sorted_errors.len() {
        let mut j = 0;
        while j < sorted_errors.len() - 1 {
            if sorted_errors[j].severity < sorted_errors[j + 1].severity {
                let temp = sorted_errors[j].clone();
                sorted_errors[j] = sorted_errors[j + 1].clone();
                sorted_errors[j + 1] = temp;
            }
            j = j + 1;
        }
        i = i + 1;
    }

    // Add recommendations
    for error in sorted_errors {
        let rec = format!(
            "Priority: {} | Type: {:?} | Affected: {} tests",
            error.severity,
            error.error_type,
            error.affected_tests.len()
        );
        recommendations.push(rec);
    }

    recommendations
}

// ===== Clone trait implementations =====

trait ErrorAnalysisCl {
    fn clone(&self) -> ErrorAnalysis;
}

impl ErrorAnalysisCl for ErrorAnalysis {
    fn clone(&self) -> ErrorAnalysis {
        ErrorAnalysis {
