        replacement_code: "cache results to avoid recomputation".to_string(),
        confidence: 0.82
    });

    // Rule 11: UndefVariable → initialize
    rules.push(PatchRule {
        error_pattern: "undefined variable".to_string(),
        fix_template: "let var = initial_value;".to_string(),
        replacement_code: "initialize before use".to_string(),
        confidence: 0.90
    });

    // Rule 12: WrongType → cast
    rules.push(PatchRule {
        error_pattern: "expected i32, found String".to_string(),
        fix_template: "value.parse::<i32>()?".to_string(),
        replacement_code: "parse string to i32".to_string(),
        confidence: 0.86
    });

    // Rule 13: EmptyArray → check
    rules.push(PatchRule {
        error_pattern: "empty array".to_string(),
        fix_template: "if arr.len() > 0 { arr[0] }".to_string(),
        replacement_code: "arr.first().unwrap_or(default)".to_string(),
        confidence: 0.91
    });

    // Rule 14: NegativeIndex → validate
    rules.push(PatchRule {
        error_pattern: "negative index".to_string(),
        fix_template: "if i >= 0 { arr[i] }".to_string(),
        replacement_code: "validate index before access".to_string(),
        confidence: 0.88
    });

    // Rule 15: StringEncoding → encode
    rules.push(PatchRule {
        error_pattern: "invalid utf-8".to_string(),
        fix_template: "String::from_utf8_lossy(bytes)".to_string(),
        replacement_code: "handle invalid utf-8 gracefully".to_string(),
        confidence: 0.83
    });

    // Rule 16: FileNotFound → check
    rules.push(PatchRule {
        error_pattern: "file not found".to_string(),
        fix_template: "if Path::new(file).exists() { }".to_string(),
        replacement_code: "check file exists before reading".to_string(),
        confidence: 0.89
    });

    // Rule 17: PermissionDenied → handle
    rules.push(PatchRule {
        error_pattern: "permission denied".to_string(),
        fix_template: "match fs::read_to_string(file) { Ok(s) => s, Err(_) => default }".to_string(),
        replacement_code: "handle permission errors".to_string(),
        confidence: 0.84
    });

    // Rule 18: DataRace → Mutex
    rules.push(PatchRule {
        error_pattern: "data race".to_string(),
        fix_template: "let data = Arc::new(Mutex::new(value));".to_string(),
        replacement_code: "use Mutex for concurrent access".to_string(),
        confidence: 0.81
    });

    // Rule 19: RecursionLimit → iterate
    rules.push(PatchRule {
        error_pattern: "stack overflow".to_string(),
        fix_template: "convert recursion to iteration".to_string(),
        replacement_code: "use loop or queue instead of recursion".to_string(),
        confidence: 0.79
    });

    // Rule 20: LoopInvariant → optimize
    rules.push(PatchRule {
        error_pattern: "loop invariant".to_string(),
        fix_template: "move calculation outside loop".to_string(),
        replacement_code: "cache loop-invariant computation".to_string(),
        confidence: 0.78
    });

    rules
}

impl PatchGenerator {
    fn new() -> PatchGenerator {
        PatchGenerator {
            rules: create_patch_rules(),
            generated_patches: vec![]
        }
    }

    fn generate_patches(mut self, error_analysis: Vec<ErrorAnalysis>) -> PatchGenerator {
        for error in error_analysis {
            let patch = self.generate_patch_for_error(error);
            self.generated_patches.push(patch);
        }
        self
    }

    fn generate_patch_for_error(&self, error: ErrorAnalysis) -> Patch {
        let mut best_match = Option::None;
        let mut best_confidence = 0.0;

        // Find matching rule
        for rule in &self.rules {
            if contains_substring(error.message.clone(), rule.error_pattern.clone()) {
                if rule.confidence > best_confidence {
                    best_confidence = rule.confidence;
                    best_match = Option::Some(rule.clone());
                }
            }
        }

        match best_match {
            Option::Some(rule) => {
                let explanation = format!(
                    "Pattern: {} → Apply: {}",
                    rule.error_pattern,
                    rule.fix_template
                );

                Patch {
                    error_type: error.error_type,
                    location: error.location,
                    original_code: format!("// Original code at {}", error.location),
                    patched_code: rule.replacement_code,
                    explanation,
                    confidence: rule.confidence
                }
            },
            Option::None => {
                Patch {
                    error_type: error.error_type,
                    location: error.location,
                    original_code: format!("// Original code at {}", error.location),
                    patched_code: "// Manual review required".to_string(),
                    explanation: "No matching pattern found".to_string(),
                    confidence: 0.0
                }
            }
        }
    }

    fn filter_by_confidence(self, min_conf: f32) -> Vec<Patch> {
        let mut result = vec![];
        for patch in self.generated_patches {
            if patch.confidence >= min_conf {
                result.push(patch);
            }
        }
        result
    }

    fn get_high_confidence_patches(self) -> Vec<Patch> {
        self.filter_by_confidence(0.85)
    }

    fn get_patch_count_by_type(self) -> Vec<(String, i32)> {
        let mut counts = vec![];

        for patch in self.generated_patches {
            let patch_type = match patch.error_type {
                ErrorType::NullPointer => "NullPointer".to_string(),
                ErrorType::BoundsError => "BoundsError".to_string(),
                ErrorType::TypeMismatch => "TypeMismatch".to_string(),
                ErrorType::PerformanceIssue => "PerformanceIssue".to_string(),
                _ => "Other".to_string()
            };

            let mut found = false;
            for (ptype, count) in &mut counts {
                if ptype == &patch_type {
                    *count = *count + 1;
                    found = true;
                    break;
                }
            }

            if !found {
                counts.push((patch_type, 1));
            }
        }

        counts
    }
}

// ===== Helper Functions =====

fn contains_substring(text: String, pattern: String) -> bool {
    let text_lower = text.to_lowercase();
    let pattern_lower = pattern.to_lowercase();

    let text_chars: Vec<char> = text_lower.chars().collect();
    let pattern_chars: Vec<char> = pattern_lower.chars().collect();

    if pattern_chars.len() > text_chars.len() {
        return false;
    }

    let mut i = 0;
    while i <= text_chars.len() - pattern_chars.len() {
        let mut matches = true;
        let mut j = 0;
        while j < pattern_chars.len() {
            if text_chars[i + j] != pattern_chars[j] {
                matches = false;
                break;
            }
            j = j + 1;
        }
        if matches {
            return true;
        }
        i = i + 1;
    }

    false
}

fn create_patch_generator() -> PatchGenerator {
    PatchGenerator::new()
}

fn generate_patches_for_errors(errors: Vec<ErrorAnalysis>) -> Vec<Patch> {
    let gen = PatchGenerator::new();
    let gen = gen.generate_patches(errors);
    gen.generated_patches
}

fn filter_patches_by_confidence(patches: Vec<Patch>, min_conf: f32) -> Vec<Patch> {
    let mut result = vec![];
    for patch in patches {
        if patch.confidence >= min_conf {
            result.push(patch);
        }
    }
    result
}

fn count_auto_fixable(patches: Vec<Patch>) -> i32 {
    let mut count = 0;
    for patch in patches {
        if patch.confidence >= 0.85 {
            count = count + 1;
        }
    }
    count
}

// ===== Clone trait implementations =====

trait PatchRuleCl {
    fn clone(&self) -> PatchRule;
}

impl PatchRuleCl for PatchRule {
    fn clone(&self) -> PatchRule {
        PatchRule {
            error_pattern: self.error_pattern.clone(),
            fix_template: self.fix_template.clone(),
            replacement_code: self.replacement_code.clone(),
            confidence: self.confidence
        }
    }
}

trait PatchCl {
    fn clone(&self) -> Patch;
}

impl PatchCl for Patch {
    fn clone(&self) -> Patch {
        Patch {
            error_type: self.error_type.clone(),
            location: self.location.clone(),
            original_code: self.original_code.clone(),
            patched_code: self.patched_code.clone(),
            explanation: self.explanation.clone(),
            confidence: self.confidence
        }
    }
}

