// Phase 3 Day 10-11: Verifier
// 패치 적용 후 검증 및 신뢰도 평가

use crate::phase3::patch_generator::*;
use crate::phase3::test_generator::*;

struct VerificationResult {
    patch: Patch,
    original_tests_pass: bool,
    new_tests_pass: bool,
    performance_improved: bool,
    memory_improved: bool,
    verdict: String,
    confidence_score: f32
}

struct Verifier {
    test_suite: Vec<TestCase>,
    original_results: Vec<bool>,
    patched_results: Vec<bool>,
    patch_results: Vec<VerificationResult>
}

// ===== Verification Logic =====

fn calculate_confidence_score(
    original_pass: i32,
    patched_pass: i32,
    perf_improved: bool,
    memory_improved: bool,
    total_tests: i32
) -> f32 {
    let mut score = 0.0;

    // Test pass rate: 50%
    if total_tests > 0 {
        let pass_rate = (patched_pass as f32 / total_tests as f32) * 100.0;
        score = score + (pass_rate / 100.0) * 50.0;
    }

    // Regression check: 30%
    if original_pass == patched_pass {
        score = score + 30.0;
    } else if original_pass > patched_pass {
        score = score - 15.0;
    } else {
        score = score + 15.0;
    }

    // Performance improvement: 10%
    if perf_improved {
        score = score + 10.0;
    }

    // Memory improvement: 10%
    if memory_improved {
        score = score + 10.0;
    }

    if score < 0.0 {
        0.0
    } else if score > 100.0 {
        100.0
    } else {
        score
    }
}

fn determine_verdict(confidence: f32) -> String {
    if confidence > 90.0 {
        "APPROVED".to_string()
    } else if confidence >= 70.0 {
        "MANUAL_REVIEW".to_string()
    } else {
        "REJECTED".to_string()
    }
}

fn simulate_test_execution(test: TestCase, use_patched: bool) -> bool {
    // Simulate test execution
    // In real scenario, this would execute the code
    // For now, we assume Positive tests pass, others depend on patch

    match test.test_type {
        TestType::Positive => true,
        TestType::EdgeCase => {
            if use_patched {
                true  // Assume patched code handles edge cases
            } else {
                false // Original might fail
            }
        },
        TestType::Negative => {
            if use_patched {
                true  // Assume patched code handles errors
            } else {
                false // Original might crash
            }
        },
        TestType::Performance => {
            true  // Assume performance tests pass
        }
    }
}

impl Verifier {
    fn new() -> Verifier {
        Verifier {
            test_suite: vec![],
            original_results: vec![],
            patched_results: vec![],
            patch_results: vec![]
        }
    }

    fn add_test_suite(mut self, tests: Vec<TestCase>) -> Verifier {
        self.test_suite = tests;
        self
    }

    fn verify_patch(mut self, patch: Patch) -> VerificationResult {
        let mut original_pass_count = 0;
        let mut patched_pass_count = 0;

        // Run tests on original code
        for test in &self.test_suite {
            let result = simulate_test_execution(test.clone(), false);
            self.original_results.push(result);
            if result {
                original_pass_count = original_pass_count + 1;
            }
        }

        // Run tests on patched code
        for test in &self.test_suite {
            let result = simulate_test_execution(test.clone(), true);
            self.patched_results.push(result);
            if result {
                patched_pass_count = patched_pass_count + 1;
            }
        }

        // Assume improvement
        let perf_improved = patch.confidence > 0.8;
        let memory_improved = patch.confidence > 0.75;

        let confidence = calculate_confidence_score(
            original_pass_count,
            patched_pass_count,
            perf_improved,
            memory_improved,
            self.test_suite.len() as i32
        );

        let verdict = determine_verdict(confidence);

        VerificationResult {
            patch,
            original_tests_pass: original_pass_count > 0,
            new_tests_pass: patched_pass_count == self.test_suite.len() as i32,
            performance_improved: perf_improved,
            memory_improved: memory_improved,
            verdict,
            confidence_score: confidence
        }
    }

    fn verify_patches(mut self, patches: Vec<Patch>) -> Vec<VerificationResult> {
        let mut results = vec![];

        for patch in patches {
            let result = self.clone().verify_patch(patch);
            results.push(result);
        }

        self.patch_results = results.clone();
        results
    }

    fn get_approved_patches(self) -> Vec<Patch> {
        let mut approved = vec![];

        for result in self.patch_results {
            if result.verdict == "APPROVED".to_string() {
                approved.push(result.patch);
            }
        }

        approved
    }

    fn get_approval_rate(self) -> f32 {
        let mut approved_count = 0;
        let total = self.patch_results.len();

        for result in self.patch_results {
            if result.verdict == "APPROVED".to_string() {
                approved_count = approved_count + 1;
            }
        }

        if total == 0 {
            0.0
        } else {
            (approved_count as f32 / total as f32) * 100.0
        }
    }

    fn get_average_confidence(self) -> f32 {
        if self.patch_results.len() == 0 {
            0.0
        } else {
            let mut total = 0.0;
            for result in self.patch_results {
                total = total + result.confidence_score;
            }
            total / self.patch_results.len() as f32
        }
    }

    fn generate_verification_report(self) -> String {
        let mut report = String::new();

        report.push_str("=== Verification Report ===\n");
        report.push_str(&format!("Total Patches: {}\n", self.patch_results.len()));
        report.push_str(&format!("Approval Rate: {:.1}%\n", self.get_approval_rate()));
        report.push_str(&format!("Average Confidence: {:.1}%\n", self.get_average_confidence()));
        report.push_str("\n--- Details ---\n");

        for result in self.patch_results {
            report.push_str(&format!(
                "Patch at {}: {} (Confidence: {:.1}%)\n",
                result.patch.location,
                result.verdict,
                result.confidence_score
            ));
        }

        report
    }
}

// ===== Helper Functions =====

fn create_verifier() -> Verifier {
    Verifier::new()
}

fn verify_patches(tests: Vec<TestCase>, patches: Vec<Patch>) -> Vec<VerificationResult> {
    let verifier = Verifier::new().add_test_suite(tests);
    verifier.verify_patches(patches)
}

fn count_approved_patches(results: Vec<VerificationResult>) -> i32 {
    let mut count = 0;
    for result in results {
        if result.verdict == "APPROVED".to_string() {
            count = count + 1;
        }
    }
    count
}

fn count_manual_review(results: Vec<VerificationResult>) -> i32 {
    let mut count = 0;
    for result in results {
        if result.verdict == "MANUAL_REVIEW".to_string() {
            count = count + 1;
        }
    }
    count
}

fn count_rejected(results: Vec<VerificationResult>) -> i32 {
    let mut count = 0;
    for result in results {
        if result.verdict == "REJECTED".to_string() {
            count = count + 1;
        }
    }
    count
}

// ===== Clone trait implementations =====

trait VerificationResultCl {
    fn clone(&self) -> VerificationResult;
}

impl VerificationResultCl for VerificationResult {
    fn clone(&self) -> VerificationResult {
        VerificationResult {
            patch: self.patch.clone(),
            original_tests_pass: self.original_tests_pass,
            new_tests_pass: self.new_tests_pass,
            performance_improved: self.performance_improved,
            memory_improved: self.memory_improved,
            verdict: self.verdict.clone(),
            confidence_score: self.confidence_score
        }
    }
}

trait VerifierCl {
    fn clone(&self) -> Verifier;
}

impl VerifierCl for Verifier {
    fn clone(&self) -> Verifier {
        let mut cloned_original = vec![];
        for result in &self.original_results {
            cloned_original.push(*result);
        }

        let mut cloned_patched = vec![];
        for result in &self.patched_results {
            cloned_patched.push(*result);
        }

        let mut cloned_patches = vec![];
        for result in &self.patch_results {
            cloned_patches.push(result.clone());
        }

        let mut cloned_tests = vec![];
        for test in &self.test_suite {
            cloned_tests.push(test.clone());
        }

        Verifier {
            test_suite: cloned_tests,
            original_results: cloned_original,
            patched_results: cloned_patched,
            patch_results: cloned_patches
        }
    }
}

