// Phase 3 Day 12-15: Self-Healing Loop Integration
// Test → Error Analysis → Patch Generation → Verification 통합

use crate::phase3::test_generator::*;
use crate::phase3::error_analyzer::*;
use crate::phase3::patch_generator::*;
use crate::phase3::verifier::*;

struct HealingSession {
    session_id: String,
    generation: i32,  // 진화 세대
    tests_generated: i32,
    errors_found: i32,
    patches_applied: i32,
    patches_approved: i32,
    proof_score: f32  // 품질 점수
}

struct HealingReport {
    session: HealingSession,
    test_summary: (i32, i32, i32),  // (total, failed, critical)
    error_summary: Vec<(String, i32)>,  // (ErrorType, count)
    patch_summary: Vec<(String, i32)>,  // (Status, count)
    overall_success: bool
}

struct SelfHealingLoopEngine {
    current_session: HealingSession,
    history: Vec<HealingReport>,
    max_generations: i32,
    target_proof_score: f32
}

// ===== Healing Loop Orchestration =====

fn create_healing_session(session_id: String) -> HealingSession {
    HealingSession {
        session_id,
        generation: 1,
        tests_generated: 0,
        errors_found: 0,
        patches_applied: 0,
        patches_approved: 0,
        proof_score: 0.0
    }
}

fn run_healing_generation(
    intent_type: IntentType,
    previous_proof_score: f32
) -> HealingSession {
    let mut session = create_healing_session(format!("session-gen-{}", previous_proof_score as i32));

    // Step 1: Test Generation
    let test_gen = create_test_generator(intent_type);
    session.tests_generated = test_gen.total_count;

    // Step 2: Generate tests and run (simulate execution)
    let all_tests = generate_all_tests();
    let mut failed_tests = vec![];

    for test in &all_tests {
        // Simulate: some tests fail
        match test.test_type {
            TestType::EdgeCase => {
                let result = TestResult {
                    test_case: test.clone(),
                    passed: false,
                    error_message: "Edge case failed".to_string(),
                    execution_time_ms: 150
                };
                failed_tests.push(result);
            },
            TestType::Negative => {
                let result = TestResult {
                    test_case: test.clone(),
                    passed: false,
                    error_message: "Negative test failed".to_string(),
                    execution_time_ms: 100
                };
                failed_tests.push(result);
            },
            _ => {}
        }
    }

    // Step 3: Error Analysis
    let analyzer = analyze_test_failures(failed_tests);
    let errors = analyzer.errors.clone();
    session.errors_found = errors.len() as i32;

    // Step 4: Patch Generation
    let patch_gen = PatchGenerator::new();
    let patch_gen = patch_gen.generate_patches(errors);
    let patches = patch_gen.generated_patches;
    session.patches_applied = patches.len() as i32;

    // Step 5: Verification
    let verifier = create_verifier().add_test_suite(all_tests);
    let results = verifier.verify_patches(patches);
    session.patches_approved = count_approved_patches(results.clone()) as i32;

    // Calculate ProofScore
    if session.tests_generated > 0 {
        let success_rate = (session.patches_approved as f32 / session.patches_applied as f32) * 100.0;
        session.proof_score = (previous_proof_score + success_rate) / 2.0;
    }

    session
}

impl SelfHealingLoopEngine {
    fn new(max_gen: i32, target_score: f32) -> SelfHealingLoopEngine {
        SelfHealingLoopEngine {
            current_session: create_healing_session("initial".to_string()),
            history: vec![],
            max_generations: max_gen,
            target_proof_score: target_score
        }
    }

    fn run_healing_loop(mut self, intent_type: IntentType) -> HealingReport {
        let mut generation = 1;
        let mut current_proof = 0.0;

        while generation <= self.max_generations && current_proof < self.target_proof_score {
            // Run one generation
            let session = run_healing_generation(intent_type, current_proof);
            current_proof = session.proof_score;

            // Generate report
            let report = HealingReport {
                session: session.clone(),
                test_summary: (
                    session.tests_generated,
                    session.errors_found,
                    session.errors_found / 2
                ),
                error_summary: vec![
                    ("NullPointer".to_string(), 2),
                    ("BoundsError".to_string(), 1),
                    ("TypeMismatch".to_string(), 1)
                ],
                patch_summary: vec![
                    ("APPROVED".to_string(), session.patches_approved),
                    ("MANUAL_REVIEW".to_string(), 1),
                    ("REJECTED".to_string(), 0)
                ],
                overall_success: session.patches_approved > 0
            };

            self.history.push(report);
            generation = generation + 1;
        }

        // Return final report
        if self.history.len() > 0 {
            self.history[self.history.len() - 1].clone()
        } else {
            HealingReport {
                session: create_healing_session("empty".to_string()),
                test_summary: (0, 0, 0),
                error_summary: vec![],
                patch_summary: vec![],
                overall_success: false
            }
        }
    }

    fn get_healing_statistics(self) -> (i32, f32, i32) {
        let total_generations = self.history.len() as i32;
        let total_patches_approved: i32 = {
            let mut count = 0;
            for report in &self.history {
                count = count + report.session.patches_approved;
            }
            count
        };

        let final_proof_score = if self.history.len() > 0 {
            self.history[self.history.len() - 1].session.proof_score
        } else {
            0.0
        };

        (total_generations, final_proof_score, total_patches_approved)
    }

    fn print_healing_report(self) -> String {
        let mut report = String::new();

        report.push_str("=== Self-Healing Loop Report ===\n");
        report.push_str(&format!("Total Generations: {}\n", self.history.len()));

        for history_item in &self.history {
            report.push_str(&format!(
                "Gen {}: {} tests, {} errors, {} patches approved (ProofScore: {:.1}%)\n",
                history_item.session.generation,
                history_item.session.tests_generated,
                history_item.session.errors_found,
                history_item.session.patches_approved,
                history_item.session.proof_score
            ));
        }

        let (_, final_score, total_approved) = self.get_healing_statistics();
        report.push_str(&format!("\nFinal ProofScore: {:.1}%\n", final_score));
        report.push_str(&format!("Total Patches Approved: {}\n", total_approved));

        report
    }
}

// ===== Helper Functions =====

fn create_healing_loop_engine(max_gen: i32, target_score: f32) -> SelfHealingLoopEngine {
    SelfHealingLoopEngine::new(max_gen, target_score)
}

fn run_self_healing_loop(intent_type: IntentType) -> HealingReport {
    let engine = create_healing_loop_engine(3, 0.75);
    engine.run_healing_loop(intent_type)
}

fn should_continue_healing(proof_score: f32, target: f32, gen: i32, max_gen: i32) -> bool {
    proof_score < target && gen < max_gen
}

// ===== Clone trait implementations =====

trait HealingSessionCl {
    fn clone(&self) -> HealingSession;
}

impl HealingSessionCl for HealingSession {
    fn clone(&self) -> HealingSession {
        HealingSession {
            session_id: self.session_id.clone(),
            generation: self.generation,
            tests_generated: self.tests_generated,
            errors_found: self.errors_found,
            patches_applied: self.patches_applied,
            patches_approved: self.patches_approved,
            proof_score: self.proof_score
        }
    }
}

trait HealingReportCl {
    fn clone(&self) -> HealingReport;
}

impl HealingReportCl for HealingReport {
    fn clone(&self) -> HealingReport {
        let mut error_summary = vec![];
        for (et, count) in &self.error_summary {
            error_summary.push((et.clone(), *count));
        }

        let mut patch_summary = vec![];
        for (ps, count) in &self.patch_summary {
            patch_summary.push((ps.clone(), *count));
        }

        HealingReport {
            session: self.session.clone(),
            test_summary: self.test_summary,
            error_summary,
            patch_summary,
            overall_success: self.overall_success
        }
    }
}

trait SelfHealingLoopEngineCl {
    fn clone(&self) -> SelfHealingLoopEngine;
}

impl SelfHealingLoopEngineCl for SelfHealingLoopEngine {
    fn clone(&self) -> SelfHealingLoopEngine {
        let mut cloned_history = vec![];
        for report in &self.history {
            cloned_history.push(report.clone());
        }

        SelfHealingLoopEngine {
            current_session: self.current_session.clone(),
            history: cloned_history,
            max_generations: self.max_generations,
            target_proof_score: self.target_proof_score
        }
    }
}

